options.styles:
& {
  display: block;
  container-type: size;
  container-name: logocontainer;
}

& .dt-row {
  height: 100%;
  display: flex;
  padding: 0;
  align-items: center;
}

& .dt-row .logo {
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  background-size: contain;
  background-position: center;
}

& .dt-row .description {
  font-size: 20pt;
  align-self: flex-start;
  margin-top: 2rem;
  width: 30%;
}


@container logocontainer ((max-width: 400px) and (max-height: 150px)) {
  & .dt-row {
    flex-direction: row;
  }

  & .dt-row .description {
    align-self: center;
    margin: 0;
    width: auto;
    font-size: 11pt;
  }
}


@container logocontainer ((max-width: 400px) and (min-height: 150px)) {
  & .dt-row {
    flex-direction: column;
  }

  & .dt-row .description {
    align-self: center;
    margin: 0;
    width: auto;
    font-size: 11pt;
  }
}

